"""Selected same-PID quota bootstrap; inert unless invoked by reviewed own unit.

The hold/source/run handshake shares ONE passed monotonic deadline, also capped
at150ms locally. Missing/late manager always runs selected business ONCE with
unqualified observation. It never waits for permission to do business.
"""
import hashlib
import json
import os
from pathlib import Path
import select
import socket
import stat
import sys
import time
import types


FALLBACK_QUOTA = bytes.fromhex('')


class ManagedObserver:
    def __init__(self, child): self.child, self.dirty = child, False
    def fail(self): self.dirty = True; self.child.dirty = True
    def emit(self, phase, **fields):
        try:
            self.child.dirty |= self.dirty
            if not self.child.emit(phase, **fields):
                self.fail(); return False
            return True
        except BaseException as error:
            self.fail()
            if not isinstance(error, Exception): raise
            return False


def run_once(selected, argv, observer):
    return selected.main(argv, _managed_observer=observer)


def acquired(path, digest):
    fd = os.open(path, os.O_RDONLY | os.O_NOFOLLOW | os.O_NONBLOCK)
    try:
        s = os.fstat(fd)
        if not stat.S_ISREG(s.st_mode) or s.st_uid != os.getuid() or s.st_nlink != 1 or s.st_mode & 0o222 or not 0 < s.st_size <= 262144:
            raise RuntimeError('source_unqualified')
        raw = os.read(fd, 262145)
        if len(raw) != s.st_size or hashlib.sha256(raw).hexdigest() != digest:
            raise RuntimeError('source_unqualified')
        return raw
    finally:
        os.close(fd)


def recv(channel, end):
    remaining = end - time.monotonic()
    if remaining <= 0 or not select.select([channel], [], [], remaining)[0]:
        raise TimeoutError()
    raw, _anc, flags, _addr = channel.recvmsg(2049, 0, socket.MSG_DONTWAIT)
    if not raw or len(raw) > 2048 or _anc or flags & (socket.MSG_TRUNC | socket.MSG_CTRUNC):
        raise RuntimeError('channel_unqualified')
    return raw


def send(channel, raw, end):
    remaining = end - time.monotonic()
    if remaining <= 0 or not select.select([], [channel], [], remaining)[1] or channel.send(raw) != len(raw):
        raise TimeoutError()


def main(argv):
    # All parameters are public hashes/time, generated in exact own ExecStart.
    leaf = Path(__file__).resolve().parent
    try:
        if len(argv) != 3: raise ValueError()
        end = min(int(argv[0]) / 1e9, time.monotonic() + .15)
    except Exception:
        end = time.monotonic()  # Missing observation config never gates business.
        argv = ['', '', '']
    channel = None
    qualified = False
    context = None
    try:
        channel = socket.socket(socket.AF_UNIX, socket.SOCK_SEQPACKET)
        channel.setblocking(False)
        try:
            channel.connect(str(leaf / 'source-gate.sock'))
        except BlockingIOError:
            pass
        send(channel, b'held-before-quota-source', end)
        command = recv(channel, end)
        if len(command) == 37 and command.startswith(b'open:'):
            context = command[5:].decode('ascii')
            if len(context) != 32 or any(c not in '0123456789abcdef' for c in context):
                raise RuntimeError('context_unqualified')
        else:
            raise RuntimeError('context_unqualified')
    except Exception:
        context = None
    # Source execution safety is independent: never execute replaced/unpinned
    # code just to fail-open observation. These are fixed selected immutable files.
    # The fixed trusted bootstrap carries the original selected business bytes.
    # Source/path/observer loss can never force execution of replacement code or
    # suppress that original action; it simply removes qualified observation.
    code = FALLBACK_QUOTA
    helper_raw = None
    try:
        actual = acquired(leaf / 'quota.py', argv[1])
        if actual != code: raise RuntimeError('source_unqualified')
        helper_raw = acquired(leaf / 'client.py', argv[2])
    except Exception:
        context = None
    if context is not None:
        try:
            send(channel, b'quota-source-opened', end)
            qualified = recv(channel, end) == b'qualified-run'
        except Exception:
            qualified = False
    selected = types.ModuleType('selected_quota_monitor')
    selected.__file__ = str(leaf / 'quota.py')
    exec(compile(code, selected.__file__, 'exec'), selected.__dict__)
    observer = None
    if qualified:
        helper = types.ModuleType('selected_quota_client')
        exec(compile(helper_raw, '<selected-quota-client>', 'exec'), helper.__dict__)
        def exchange(_path, request, *, deadline=None):
            stop = min(time.monotonic() + .15, deadline) if deadline is not None else time.monotonic() + .15
            send(channel, helper.encode(request, helper.FRAME), stop)
            return helper.decode(recv(channel, stop), helper.REPLY)
        helper.exchange = exchange  # Only this newly compiled private module.
        observer = ManagedObserver(helper.Client(None, context, None, 'quota_monitor'))
    original = None
    try:
        # Fixed own synthetic state; check never invokes hub/quse/provider. The
        # forced fixture has no real SMTP even if its fresh state becomes stale.
        return run_once(selected, ['--check', '--accounts', 'codex', '--state', str(leaf / 'state.json'),
            '--alert-command', '/usr/bin/false', '--alert-timeout', '1'], observer)
    except BaseException as error:
        original = error
        raise
    finally:
        try:
            if channel is not None: channel.close()
        except BaseException as error:
            if observer is not None: observer.fail()
            if original is None and not isinstance(error, Exception): raise


if __name__ == '__main__':
    if len(sys.argv) == 1:
        print(json.dumps({'status':'INERT_HOLD','authority':'NONE','complete':False}))
    elif sys.argv[1] != '--execute-owned-fixture':
        raise SystemExit(2)
    else:
        raise SystemExit(main(sys.argv[2:]))
